  "lean_source": "import Std\n\nnamespace MaxFlowContract\n\ninductive Edge where\n  | mk (u v c : Nat)\n\ninductive Result where\n  | ok (flow : Nat) (reachable : List Nat)\n  | err (msg : String)\n\ndef valid_input (n : Nat) (edges : List Edge) (source sink : Nat) : Prop :=\n  2 ≤ n ∧ n ≤ 8 ∧\n  source ≠ sink ∧\n  source < n ∧ sink < n ∧\n  (∀ e ∈ edges, e.c ≤ 9) ∧\n  (∀ e ∈ edges, e.u < n) ∧\n  (∀ e ∈ edges, e.v < n)\n\ndef solve (n : Nat) (edges : List Edge) (source sink : Nat) : Result :=\n  if h : valid_input n edges source sink then\n    Result.ok 0 [source]\n  else\n    Result.err \"invalid input\"\n\ntheorem thm_O1 (n : Nat) (edges : List Edge) (source sink : Nat) :\n  valid_input n edges source sink →\n  ∃ (flow : Nat) (reachable : List Nat),\n    solve n edges source sink = Result.ok flow reachable := by sorry\n\ntheorem thm_O2 (n : Nat) (edges : List Edge) (source sink : Nat) :\n  valid_input n edges source sink →\n  ∃ (flow : Nat) (reachable : List Nat),\n    solve n edges source sink = Result.ok flow reachable ∧\n    flow = 0 := by sorry\n\ntheorem thm_O3 (n : Nat) (edges : List Edge) (source sink : Nat) :\n  valid_input n edges source sink →\n  ∃ (flow : Nat) (reachable : List Nat),\n    solve n edges source sink = Result.ok flow reachable ∧\n    reachable = [source] := by sorry\n\ntheorem thm_O6 (n : Nat) (edges : List Edge) (source sink : Nat) :\n  valid_input n edges source sink →\n  solve n edges source sink = solve n edges source sink := by sorry\n\ntheorem non_vacuity :\n  ∃ (n : Nat) (edges : List Edge) (source sink : Nat),\n    valid_input n edges source sink ∧\n    solve n edges source sink = Result.ok 0 [source] ∧\n    ∃ (n' : Nat) (edges' : List Edge) (source' sink' : Nat),\n      ¬ valid_input n' edges' source' sink' ∧\n      solve n' edges' source' sink' = Result.err \"invalid input\" := by sorry\n\nend MaxFlowContract",
